export async function taskRoutes(app: FastifyInstance): Promise<void> {
  const controller = new TasksController();

  app.get('/tasks', { schema: { querystring: listTasksQuerySchema } }, controller.list);

  app.get('/tasks/:id', { schema: { params: taskIdParamsSchema } }, controller.getById);

  app.post('/tasks', { schema: { body: createTaskSchema } }, controller.create);

  app.patch(
    '/tasks/:id',
    { schema: { params: taskIdParamsSchema, body: updateTaskSchema } },
    controller.update,
  );

  app.delete('/tasks/:id', { schema: { params: taskIdParamsSchema } }, controller.remove);
}

export interface TaskRepository {
  findById(id: string): Promise<Task | null>;
  list(query: TaskQuery): Promise<Page<Task>>;
  create(task: Task): Promise<Task>;
  update(task: Task): Promise<Task>;
  delete(id: string): Promise<boolean>;
}

async list(
  request: FastifyRequest<{ Querystring: ListTasksQuery }>,
  reply: FastifyReply,
): Promise<void> {
  const page = await request.server.taskService.list(request.query);
  await reply.send(page);
}

async getById(
  request: FastifyRequest<{ Params: TaskIdParams }>,
  reply: FastifyReply,
): Promise<void> {
  const task = await request.server.taskService.get(request.params.id);
  await reply.send(task);
}

async create(
  request: FastifyRequest<{ Body: CreateTaskBody }>,
  reply: FastifyReply,
): Promise<void> {
  const task = await request.server.taskService.create(request.body);
  await reply.code(201).send(task);
}

async update(
  request: FastifyRequest<{ Params: TaskIdParams; Body: UpdateTaskBody }>,
  reply: FastifyReply,
): Promise<void> {
  const task = await request.server.taskService.update(request.params.id, request.body);
  await reply.send(task);
}

async remove(
  request: FastifyRequest<{ Params: TaskIdParams }>,
  reply: FastifyReply,
): Promise<void> {
  await request.server.taskService.delete(request.params.id);
  await reply.code(204).send();
}

export class TaskService {
  constructor(
    private readonly repository: TaskRepository,
    private readonly clock: () => string = () => new Date().toISOString(),
  ) {}

  async get(id: string): Promise<Task> {
    const task = await this.repository.findById(id);
    if (!task) throw new TaskNotFoundError(id);
    return task;
  }

  async list(query: TaskQuery): Promise<Page<Task>> {
    return this.repository.list(query);
  }

  async create(input: CreateTaskInput): Promise<Task> {
    const now = this.clock();
    const task: Task = {
      id: newId(),
      title: input.title,
      description: input.description ?? null,
      status: input.status ?? 'todo',
      priority: input.priority ?? 'medium',
      tags: input.tags ?? [],
      dueDate: input.dueDate ?? null,
      createdAt: now,
      updatedAt: now,
    };
    return this.repository.create(task);
  }

  async update(id: string, input: UpdateTaskInput): Promise<Task> {
    const current = await this.get(id);

    if (input.status && input.status !== current.status) {
      if (!canTransition(current.status, input.status)) {
        throw new IllegalStatusTransitionError(current.status, input.status);
      }
    }

    const updated: Task = {
      ...current,
      ...pruneUndefined(input),
      id: current.id,
      createdAt: current.createdAt,
      updatedAt: this.clock(),
    };
    return this.repository.update(updated);
  }

  async delete(id: string): Promise<void> {
    const deleted = await this.repository.delete(id);
    if (!deleted) throw new TaskNotFoundError(id);
  }
}

export function buildPage<T>(items: T[], total: number, page: number, pageSize: number): Page<T> {
  return {
    items,
    total,
    page,
    pageSize,
    pageCount: pageSize > 0 ? Math.ceil(total / pageSize) : 0,
  };
}

async list(query: TaskQuery): Promise<Page<Task>> {
  const all = [...this.tasks.values()];
  const filtered = applyFilters(all, query);
  const sorted = sortTasks(filtered, query.sort, query.order);
  const total = sorted.length;
  const start = (query.page - 1) * query.pageSize;
  const items = sorted.slice(start, start + query.pageSize);
  return buildPage(items, total, query.page, query.pageSize);
}

